import { crypto } from "node:crypto";

export function timingSafeEqual(a: string, b: string): boolean {
  const aBytes = new TextEncoder().encode(a);
  const bBytes = new TextEncoder().encode(b);

  // Early return if lengths differ
  if (aBytes.length !== bBytes.length) {
    return false;
  }

  // Constant-time comparison
  let result = 0;
  const len = aBytes.length;

  for (let i = 0; i < len; i++) {
    // Use XOR and bitwise OR to avoid short-circuiting
    result |= aBytes[i] ^ bBytes[i];
  }

  return result === 0;
}

export function getRandomDelay(minMs: number, maxMs: number): number {
  const range = maxMs - minMs;
  const randomBytes = crypto.randomBytes(4);
  const randomValue = randomBytes.readUInt32BE(0);
  const jitter = (randomValue / 0xffffffff) * range;
  return minMs + Math.floor(jitter);
}

